"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[9439],{89439:a=>{a.exports=JSON.parse('{"slug":"tarify-gaz-elektrichestvo-oktyabr-2026","locale":"zh","title":"2026年十月1日起天然气涨9.6%、居民电价涨11.3%","description":"2026年十月1日起居民电价涨11.3%、天然气9.6%。分解账单、卢布影响及2027年七月下一次调整。","blocks":[{"id":"b001","kind":"paragraph","text":"2026年十月1日俄罗斯天然气和电力涨价。Gazprom气价批发上调9.6%，月用电不超过3900千瓦时的居民电价涨11.3%。居民气电价格不由市场而由政府按预测时间和幅度制定，称管制定价。因此2026年的调整一年前已在经济预测中可见。"},{"id":"b002","kind":"paragraph","text":"燃气账单三部分：气体本身80%，管输到户15%，开票服务5%。十月1日分别调9.6%、11.6%和5.1%。加权总账单约增9.7%（0.8 \xd7 9.6 + 0.15 \xd7 11.6 + 0.05 \xd7 5.1）。"},{"id":"b003","kind":"paragraph","text":"电力同理，终端价由发电与电网输送组成。主干电网ENES收费涨16%，地方配电15.2%，居民终价只增11.3%。输送大涨，但仅占账单一部分。"},{"id":"b004","kind":"paragraph","text":"换算卢布，家庭原来每1000卢布电费多113，燃气约多97。莫斯科有燃气灶公寓每千瓦时从8到8.9卢布，月200千瓦时者付1780而非1600，多180。地方当局在联邦反垄断局框架内批准居民费率。"},{"id":"b005","kind":"paragraph","text":"十月不是最后一次。2027年七月1日起，天然气再涨10.4%，此前计划9.1%。两次连续调整使批发气价9个月约涨21%（1.096 \xd7 1.104）。2027年七月居民配电费涨17.5%。通常七月调整，2027年起回归该时间表。"},{"id":"b006","kind":"paragraph","text":"普通人可这样判断：计量表、节能灯和保温在大账单场景更快回本，例如电采暖独栋；小公寓则较慢。2027年七月调整可预先纳入家庭预算，但幅度已被改过一次。"},{"id":"b007","kind":"heading","text":"2026年十月1日起天然气涨多少？"},{"id":"b008","kind":"paragraph","text":"批发气价9.6%，配气运输11.6%，燃气公司服务5.1%，账单合计约9.7%。"},{"id":"b009","kind":"heading","text":"2026年十月1日起电价涨多少？"},{"id":"b010","kind":"paragraph","text":"居民月用量不超过3900千瓦时时涨11.3%；电网费涨得更多，为15.2–16%。"},{"id":"b011","kind":"heading","text":"下一次气电调价何时？"},{"id":"b012","kind":"paragraph","text":"2027年七月1日。天然气涨10.4%，居民配电费涨17.5%，后者只是终端电价的一部分。"}],"sources":[{"label":"Gazprom管制气价调整9.6%","url":"https://www.interfax.ru/business/1119546"},{"label":"反垄断局将十月1日起天然气收费上调9.6%","url":"https://www.garant.ru/news/1947004/"},{"label":"十月配电费涨15.2%，统一主干网涨16%","url":"https://www.interfax.ru/russia/1119539"},{"label":"反垄断局检查地方电价","url":"https://www.kommersant.ru/doc/8990884"},{"label":"2026年莫斯科电价","url":"https://t-j.ru/msk-electroprices/"},{"label":"莫斯科2026电价表","url":"https://www.vesti.ru/vj/tarify-na-ehlektroehnergiyu-v-moskve"}],"sourceBodySha256":"b809a176f95ae120cd852b989f922de8a276fc4ea55fc40cff70d0caebfcadd4"}')}}]);